def tamper(raw, flags):
    it = iter(flags)
    return re.sub(r',"reject":(?:true|false)',
                  lambda m: ',"reject":' + ("true" if next(it) else "false"), raw)
flags1 = [i % 3 == 0 for i in range(len(positions))]
flags2 = [i % 3 != 1 for i in range(len(positions))]
